"""How the tree moved: counts say *how many*, this says *which* (plan D16, checkpoint B1).

The counts half was never the weak one. `object_counts` moving by exactly -1 is compatible with
any person leaving, and a tool's report cannot settle which: `gramps_id` in a delete report is
the echo of the argument (`gramps_client.py:1078`) and `deleted: True` is a literal. So the
identity half has to run whenever the counts move, not only when they are expected to hold
still — which is where it used to live, and therefore never ran for a create or a delete.

Three things follow from having to name identity rather than digest it:

* **Handles, projected onto ids.** A set difference over handles is what actually detects
  arrival and departure; the ids are what a test can write down. A `gramps_id` edited under an
  unchanged handle moves neither set, so it is reported separately (`renamed`) — no count and
  no id-set difference can see it, and every later step of a use case keys off the id.
* **Objects that have no `gramps_id`.** Tags do not carry one, so projecting on it alone would
  make every tag the same object; they are named `handle:<handle>` instead.
* **A loss has to be declared.** `expect_removed` is required for every namespace with a
  negative delta (the rule itself lives in `gate.py`, with the other pre-call refusals),
  because "something vanished" is satisfied just as well by the wrong thing vanishing. A
  create cannot be declared — the id is the server's to assign — so a positive delta is held
  to "exactly this many appeared, none left" and the id the tool reports has to be one of them
  (`self_report.assert_new_id_resolves`).

`EVERYTHING` exists because `delete_all_objects` is otherwise unexpressible: nobody writes out
391 ids, and "all of the ones that were there" is exactly as checkable.
"""

from __future__ import annotations

from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass
from typing import Any


class _Everything:
    """Sentinel: every id the namespace held *before* the call.

    Resolved against the before-snapshot rather than treated as a wildcard — a test that uses
    it where only part of a namespace went away over-claims, and finds out.
    """

    __slots__ = ()

    def __repr__(self) -> str:
        return "EVERYTHING"


EVERYTHING = _Everything()

# `{namespace: [gramps_id, …]}` or `{namespace: EVERYTHING}`.
Declared = Mapping[str, "Sequence[str] | _Everything"]


@dataclass(frozen=True)
class Movement:
    """What the oracle saw move between two snapshots, per namespace."""

    delta: dict[str, int]
    added: dict[str, list[str]]
    removed: dict[str, list[str]]
    renamed: dict[str, list[tuple[str, str]]]


def names_of(pairs: Iterable[Any]) -> dict[str, str]:
    """`handle -> the name this suite calls that object by`, from a snapshot's object list."""
    named = {}
    for gramps_id, handle in pairs:
        named[handle] = gramps_id or f"handle:{handle}"
    return named


def movement_of(before: Mapping[str, Any], after: Mapping[str, Any]) -> Movement:
    """Diff two `GrampsRest.snapshot()` results. Pure: it asserts nothing."""
    counts_before, counts_after = before.get("counts", {}), after.get("counts", {})
    objects_before, objects_after = before.get("objects", {}), after.get("objects", {})
    delta = {
        namespace: counts_after.get(namespace, 0) - counts_before.get(namespace, 0)
        for namespace in set(counts_before) | set(counts_after)
    }
    added: dict[str, list[str]] = {}
    removed: dict[str, list[str]] = {}
    renamed: dict[str, list[tuple[str, str]]] = {}
    for namespace in sorted(set(objects_before) | set(objects_after)):
        was = names_of(objects_before.get(namespace, ()))
        now = names_of(objects_after.get(namespace, ()))
        gone = sorted(was[handle] for handle in was.keys() - now.keys())
        arrived = sorted(now[handle] for handle in now.keys() - was.keys())
        edited = sorted(
            (was[handle], now[handle])
            for handle in was.keys() & now.keys()
            if was[handle] != now[handle]
        )
        if gone:
            removed[namespace] = gone
        if arrived:
            added[namespace] = arrived
        if edited:
            renamed[namespace] = edited
    return Movement(delta=delta, added=added, removed=removed, renamed=renamed)


def assert_tree_moved_exactly(
    name: str,
    before: Mapping[str, Any],
    after: Mapping[str, Any],
    expect_delta: Mapping[str, int],
    note: str,
    *,
    expect_added: Declared | None = None,
    expect_removed: Declared | None = None,
) -> Movement:
    """The independent half: the counts moved as promised, and so did the objects behind them."""
    movement = movement_of(before, after)
    counts_before, counts_after = before["counts"], after["counts"]
    moved = {key: value for key, value in movement.delta.items() if value}
    want = {key: value for key, value in dict(expect_delta).items() if value}

    assert moved == want, (
        f"{name}: the tree moved {moved}, expected {want}\n"
        f"  before={counts_before}\n  after={counts_after}\n  {note}"
    )
    _assert_identity_moved(name, movement, before, expect_added, expect_removed, note)
    return movement


def _assert_identity_moved(
    name: str,
    movement: Movement,
    before: Mapping[str, Any],
    expect_added: Declared | None,
    expect_removed: Declared | None,
    note: str,
) -> None:
    assert not movement.renamed, (
        f"{name}: {movement.renamed} — a gramps_id changed under an unchanged handle, an "
        f"identity change that no count and no id-set difference can see\n  {note}"
    )
    declared_added = dict(expect_added or {})
    declared_removed = dict(expect_removed or {})
    namespaces = (
        set(movement.delta)
        | set(movement.added)
        | set(movement.removed)
        | set(declared_added)
        | set(declared_removed)
    )
    for namespace in sorted(namespaces):
        added = movement.added.get(namespace, [])
        removed = movement.removed.get(namespace, [])
        if namespace in declared_added or namespace in declared_removed:
            _assert_declared(
                name, namespace, added, removed, before, declared_added, declared_removed, note
            )
        else:
            _assert_pure(name, namespace, added, removed, movement.delta.get(namespace, 0), note)


def _assert_declared(
    name: str,
    namespace: str,
    added: list[str],
    removed: list[str],
    before: Mapping[str, Any],
    declared_added: Mapping[str, Any],
    declared_removed: Mapping[str, Any],
    note: str,
) -> None:
    """Naming one side of a namespace names both: an undeclared side must be empty.

    Otherwise `expect_removed={"people": [X]}` would leave a create in the same namespace
    unremarked, which is the shape it was introduced to make visible.
    """
    want_added = _resolve(declared_added.get(namespace, []), before, namespace)
    want_removed = _resolve(declared_removed.get(namespace, []), before, namespace)
    assert added == want_added, (
        f"{name}: {namespace} gained {added or 'nothing'}, the test declared "
        f"{want_added or 'nothing'}\n  {note}"
    )
    assert removed == want_removed, (
        f"{name}: {namespace} lost {removed or 'nothing'}, the test declared "
        f"{want_removed or 'nothing'}\n  {note}"
    )


def _assert_pure(
    name: str, namespace: str, added: list[str], removed: list[str], delta: int, note: str
) -> None:
    """Undeclared, a namespace may only move one way: a delta accounts for arrivals *or*
    departures, never both. Churn that nets out is the swap this whole check exists for."""
    assert len(added) == max(delta, 0) and len(removed) == max(-delta, 0), (
        f"{name}: {namespace} changed identity by +{len(added)}/-{len(removed)}, but a delta of "
        f"{delta:+d} accounts for +{max(delta, 0)}/-{max(-delta, 0)}\n"
        f"  appeared={added or 'nothing'}\n  vanished={removed or 'nothing'}\n"
        "  declare both sides with expect_added=/expect_removed= if this churn is intended\n"
        f"  {note}"
    )


def _resolve(declared: Any, before: Mapping[str, Any], namespace: str) -> list[str]:
    if declared is EVERYTHING:
        return sorted(names_of(before.get("objects", {}).get(namespace, ())).values())
    return sorted(declared)
